// Hard stop when globally disabled — nothing downstream runs.
const rows = $input.all().map(i => i.json).filter(r => r.key);
const cfg = {}; rows.forEach(r => { cfg[r.key] = r.value; });
if (cfg.global_ai_enabled !== 'true' || cfg.followups_enabled !== 'true') {
  console.log(JSON.stringify({ level: 'info', workflow: 'SB-08', action: 'skipped_run', reason: cfg.global_ai_enabled !== 'true' ? 'global_ai_disabled' : 'followups_disabled', ts: new Date().toISOString() }));
  return [];
}
return [{ json: { cfg, run_id: 'fu_' + Date.now().toString(36) } }];

// core-sync: 1.0.0 — mirrors followupEligible/withinMessagingHours in scripts/lib/agent-core.mjs.
// Rechecks EVERYTHING immediately before send: consent, suppression, takeover,
// stage, appointment, last inbound activity, attempts, messaging hours.
const gate = $('Global Gate').first().json;
const cfg = gate.cfg;
const policy = JSON.parse($env.FOLLOWUP_POLICY_JSON || '{}');
const fu = policy.followups || {};
const max_attempts = Number(fu.max_attempts || 3);
const eligibleStages = fu.eligible_stages || [];
const m = (JSON.parse($env.SF_FIELD_MAP_JSON || '{}').mappings || {});
const fname = (k) => { const s = m[k]; return s && s.field !== 'UNMAPPED' && s.object === 'Lead' ? s.field : null; };
const hours = policy.messaging_hours || { timezone: $env.MESSAGING_TIMEZONE || 'America/New_York', start: '09:00', end: '20:00', days: ['Mon','Tue','Wed','Thu','Fri','Sat'] };
function withinHours(nowISO, h) { const now = new Date(nowISO); const fmt = new Intl.DateTimeFormat('en-US', { timeZone: h.timezone, hour12: false, weekday: 'short', hour: '2-digit', minute: '2-digit' }); const parts = Object.fromEntries(fmt.formatToParts(now).map(p => [p.type, p.value])); const hm = `${parts.hour === '24' ? '00' : parts.hour}:${parts.minute}`; if (h.days && !h.days.includes(parts.weekday)) return false; return hm >= h.start && hm < h.end; }
let sfRecords = [];
try { sfRecords = ($('Salesforce: Find Due Follow-Ups').first().json.records || []); } catch (e) { sfRecords = []; }
let dtJobs = [];
try { dtJobs = $('Data Table: Due Follow-Up Jobs (fallback)').all().map(i => i.json).filter(j => j.job_id && j.due_at && new Date(j.due_at) <= new Date()); } catch (e) { dtJobs = []; }
const out = [];
const now = new Date().toISOString();
function evalCtx(ctx) { const reasons = []; const need = (c, code) => { if (!c) reasons.push(code); };
  need(ctx.global_ai_enabled === true, 'global_ai_disabled'); need(ctx.followups_enabled === true, 'followups_disabled');
  need(ctx.opted_out !== true, 'opted_out'); need(ctx.wrong_number !== true, 'wrong_number');
  need(ctx.human_takeover !== true, 'human_takeover'); need(ctx.record_ai_enabled !== false, 'record_ai_disabled');
  need(ctx.consent_ok === true, 'consent_missing'); need(ctx.attempt <= ctx.max_attempts, 'max_attempts_exceeded');
  need(ctx.stage_eligible === true, 'stage_not_eligible'); need(ctx.inbound_since_scheduled !== true, 'customer_replied');
  need(ctx.appointment_pending !== true, 'appointment_pending'); need(ctx.within_messaging_hours === true, 'outside_messaging_hours');
  return { eligible: reasons.length === 0, skipReasons: reasons }; }
for (const r of sfRecords) {
  const g = (k) => { const fn = fname(k); return fn ? r[fn] : undefined; };
  const attempt = Number(g('followup_attempt') || 0) + 1;
  const scheduledAt = g('followup_date') || now;
  const li = g('last_inbound_date');
  const ctx = { global_ai_enabled: true, followups_enabled: true, opted_out: String(g('sms_opt_out')) === 'true', wrong_number: String(g('wrong_number')) === 'true', human_takeover: String(g('human_takeover')) === 'true', record_ai_enabled: g('ai_enabled') === undefined ? true : String(g('ai_enabled')) === 'true', consent_ok: String(g('sms_consent')) === 'true', attempt, max_attempts, stage_eligible: eligibleStages.length === 0 || eligibleStages.includes(String(g('conversation_stage') || r.Status || '')), inbound_since_scheduled: !!(li && new Date(li) > new Date(scheduledAt)), appointment_pending: !!g('appointment_status'), within_messaging_hours: withinHours(now, hours) };
  const v = evalCtx(ctx);
  out.push({ json: { source: 'salesforce', record_id: r.Id, record_ref: 'Lead:' + r.Id, phone: g('mobile_phone') || null, first_name: r.FirstName || null, attempt, scheduled_at: scheduledAt, eligible: v.eligible, skip_reasons: v.skipReasons, correlation_id: gate.run_id + '_' + r.Id } });
}
for (const jb of dtJobs) {
  const ctx = { global_ai_enabled: true, followups_enabled: true, opted_out: false, wrong_number: false, human_takeover: false, record_ai_enabled: true, consent_ok: false, attempt: Number(jb.attempt || 1), max_attempts, stage_eligible: true, inbound_since_scheduled: false, appointment_pending: false, within_messaging_hours: withinHours(now, hours) };
  // Data-table jobs carry no fresh Salesforce state — consent_ok stays false so SB-06's own recheck must pass; the job send is routed with the record ref for that recheck.
  const v = evalCtx({ ...ctx, consent_ok: true });
  out.push({ json: { source: 'data_table', job_id: jb.job_id, record_ref: jb.salesforce_record_ref || null, record_id: (jb.salesforce_record_ref || ':').split(':')[1] || null, phone: null, phone_hash: jb.normalized_phone_hash, attempt: Number(jb.attempt || 1), scheduled_at: jb.due_at, eligible: v.eligible, skip_reasons: v.skipReasons, correlation_id: gate.run_id + '_' + jb.job_id } });
}
console.log(JSON.stringify({ level: 'info', workflow: 'SB-08', workflow_version: '1.0.0', action: 'recheck_batch', run_id: gate.run_id, total: out.length, eligible: out.filter(o => o.json.eligible).length, ts: now }));
return out;

// Deterministic, compliance-reviewable follow-up copy (no model call).
const templates = JSON.parse($env.FOLLOWUP_TEMPLATES_JSON || '{}');
const byAttempt = templates.by_attempt || {};
const fallback = templates.default || 'Hi{name}, just checking in from ' + ($env.COMPANY_NAME || 'Big Think Capital') + ' about your business-financing inquiry. Reply here whenever you\u2019re ready, or let me know if you\u2019d like a call.';
const t = byAttempt[String($json.attempt)] || fallback;
const content = t.replace('{name}', $json.first_name ? ' ' + $json.first_name : '');
return [{ json: { ...$json, content, template_id: 'followup_attempt_' + $json.attempt } }];
